import{_ as t,a0 as o,w as r,s as c,ao as l,I as p,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181017 Chrony - An Alternative NTP Client And Server For Unix-like Systems","title":"Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品","tag":"201811","desc":""},"relativePath":"201811/20181017 Chrony - An Alternative NTP Client And Server For Unix-like Systems.md","filePath":"[post].md"}'),d={name:"201811/20181017 Chrony - An Alternative NTP Client And Server For Unix-like Systems.md"};function h(u,s,g,k,b,y){const a=o("Link");return r(),c("div",null,[s[18]||(s[18]=l(`<h1 id="chrony-一個類-unix-系統上-ntp-客户端和服務器替代品" tabindex="-1">Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品 <a class="header-anchor" href="#chrony-一個類-unix-系統上-ntp-客户端和服務器替代品" aria-label="Permalink to “Chrony：一個類 Unix 系統上 NTP 客户端和服務器替代品”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/chrony-1-720x340.jpeg" alt=""></p><p>在這個教程中，我們會討論如何安裝和配置 <strong>Chrony</strong>，一個類 Unix 系統上 NTP 客户端和服務器的替代品。Chrony 可以更快的同步系統時鐘，具有更好的時鐘準確度，並且它對於那些不是一直在線的系統很有幫助。Chrony 是自由開源的，並且支持 GNU/Linux 和 BSD 衍生版（比如 FreeBSD、NetBSD）、macOS 和 Solaris 等。</p><h3 id="安裝-chrony" tabindex="-1">安裝 Chrony <a class="header-anchor" href="#安裝-chrony" aria-label="Permalink to “安裝 Chrony”">​</a></h3><p>Chrony 可以從大多數 Linux 發行版的默認軟件庫中獲得。如果你使用的是 Arch Linux，運行下面的命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S chrony</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install chrony</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install chrony</span></span></code></pre></div><p>當安裝完成後，如果之前沒有啓動過的話需啓動 <code>chronyd.service</code> 守護進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start chronyd.service</span></span></code></pre></div><p>使用下面的命令讓它每次重啓系統後自動運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable chronyd.service</span></span></code></pre></div><p>為了確認 <code>chronyd.service</code> 已經啓動，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status chronyd.service</span></span></code></pre></div><p>如果一切正常，你將看到類似下面的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>● chrony.service - chrony, an NTP client/server</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/chrony.service; enabled; vendor preset: ena</span></span>
<span class="line"><span>Active: active (running) since Wed 2018-10-17 10:34:53 UTC; 3min 15s ago</span></span>
<span class="line"><span>Docs: man:chronyd(8)</span></span>
<span class="line"><span>man:chronyc(1)</span></span>
<span class="line"><span>man:chrony.conf(5)</span></span>
<span class="line"><span>Main PID: 2482 (chronyd)</span></span>
<span class="line"><span>Tasks: 1 (limit: 2320)</span></span>
<span class="line"><span>CGroup: /system.slice/chrony.service</span></span>
<span class="line"><span>└─2482 /usr/sbin/chronyd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver systemd[1]: Starting chrony, an NTP client/server...</span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver chronyd[2482]: chronyd version 3.2 starting (+CMDMON</span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver chronyd[2482]: Initial frequency -268.088 ppm</span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver systemd[1]: Started chrony, an NTP client/server.</span></span>
<span class="line"><span>Oct 17 10:35:03 ubuntuserver chronyd[2482]: Selected source 85.25.84.166</span></span>
<span class="line"><span>Oct 17 10:35:03 ubuntuserver chronyd[2482]: Source 85.25.84.166 replaced with 2403</span></span>
<span class="line"><span>Oct 17 10:35:03 ubuntuserver chronyd[2482]: Selected source 91.189.89.199</span></span>
<span class="line"><span>Oct 17 10:35:06 ubuntuserver chronyd[2482]: Selected source 106.10.186.200</span></span></code></pre></div><p>可以看到，Chrony 服務已經啓動並且正在工作！</p><h3 id="配置-chrony" tabindex="-1">配置 Chrony <a class="header-anchor" href="#配置-chrony" aria-label="Permalink to “配置 Chrony”">​</a></h3><p>NTP 客户端需要知道它要連接到哪個 NTP 服務器來獲取當前時間。我們可以直接在該 NTP 配置文件中的 <code>server</code> 或者 <code>pool</code> 項指定 NTP 服務器。通常，默認的配置文件位於 <code>/etc/chrony/chrony.conf</code> 或者 <code>/etc/chrony.conf</code>，取決於 Linux 發行版版本。為了更可靠的同步時間，建議指定至少三個服務器。</p><p>下面幾行是我的 Ubuntu 18.04 LTS 服務器上的一個示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span># About using servers from the NTP Pool Project in general see (LP: #104525).</span></span>
<span class="line"><span># Approved by Ubuntu Technical Board on 2011-02-08.</span></span>
<span class="line"><span># See http://www.pool.ntp.org/join.html for more information.</span></span>
<span class="line"><span>pool ntp.ubuntu.com iburst maxsources 4</span></span>
<span class="line"><span>pool 0.ubuntu.pool.ntp.org iburst maxsources 1</span></span>
<span class="line"><span>pool 1.ubuntu.pool.ntp.org iburst maxsources 1</span></span>
<span class="line"><span>pool 2.ubuntu.pool.ntp.org iburst maxsources 2</span></span>
<span class="line"><span>[...]</span></span></code></pre></div>`,23)),p("p",null,[s[1]||(s[1]=n("從上面的輸出中你可以看到，",-1)),e(a,{href:"https://www.ntppool.org/en/"},{default:i(()=>[...s[0]||(s[0]=[n("NTP 服務器池項目",-1)])]),_:1}),s[2]||(s[2]=n(" 已經被設置成為了默認的時間服務器。對於那些好奇的人，NTP 服務器池項目是一個時間服務器集羣，用來為全世界千萬個客户端提供 NTP 服務。它是 Ubuntu 以及其他主流 Linux 發行版的默認時間服務器。",-1))]),s[19]||(s[19]=l(`<p>在這裏，</p><ul><li><code>iburst</code> 選項用來加速初始的同步過程</li><li><code>maxsources</code> 代表 NTP 源的最大數量</li></ul><p>請確保你選擇的 NTP 服務器是同步的、穩定的、離你的位置較近的，以便使用這些 NTP 源來提升時間準確度。</p><h3 id="在命令列中管理-chronyd" tabindex="-1">在命令列中管理 Chronyd <a class="header-anchor" href="#在命令列中管理-chronyd" aria-label="Permalink to “在命令列中管理 Chronyd”">​</a></h3><p>chrony 有一個命令列工具叫做 <code>chronyc</code> 用來控制和監控 chrony 守護進程（<code>chronyd</code>）。</p><p>為了檢查是否 chrony 已經同步，我們可以使用下面展示的 <code>tracking</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc tracking</span></span>
<span class="line"><span>Reference ID : 6A0ABAC8 (t1.time.sg3.yahoo.com)</span></span>
<span class="line"><span>Stratum : 3</span></span>
<span class="line"><span>Ref time (UTC) : Wed Oct 17 11:48:51 2018</span></span>
<span class="line"><span>System time : 0.000984587 seconds slow of NTP time</span></span>
<span class="line"><span>Last offset : -0.000912981 seconds</span></span>
<span class="line"><span>RMS offset : 0.007983995 seconds</span></span>
<span class="line"><span>Frequency : 23.704 ppm slow</span></span>
<span class="line"><span>Residual freq : +0.006 ppm</span></span>
<span class="line"><span>Skew : 1.734 ppm</span></span>
<span class="line"><span>Root delay : 0.089718960 seconds</span></span>
<span class="line"><span>Root dispersion : 0.008760406 seconds</span></span>
<span class="line"><span>Update interval : 515.1 seconds</span></span>
<span class="line"><span>Leap status : Normal</span></span></code></pre></div><p>我們可以使用命令確認現在 chrony 使用的時間源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc sources</span></span>
<span class="line"><span>210 Number of sources = 8</span></span>
<span class="line"><span>MS Name/IP address Stratum Poll Reach LastRx Last sample</span></span>
<span class="line"><span>===============================================================================</span></span>
<span class="line"><span>^- chilipepper.canonical.com 2 10 377 296 +102ms[ +104ms] +/- 279ms</span></span>
<span class="line"><span>^- golem.canonical.com 2 10 377 302 +105ms[ +107ms] +/- 290ms</span></span>
<span class="line"><span>^+ pugot.canonical.com 2 10 377 297 +36ms[ +38ms] +/- 238ms</span></span>
<span class="line"><span>^- alphyn.canonical.com 2 10 377 279 -43ms[ -42ms] +/- 238ms</span></span>
<span class="line"><span>^- dadns.cdnetworks.co.kr 2 10 377 1070 +40ms[ +42ms] +/- 314ms</span></span>
<span class="line"><span>^* t1.time.sg3.yahoo.com 2 10 377 169 -13ms[ -11ms] +/- 80ms</span></span>
<span class="line"><span>^+ sin1.m-d.net 2 10 275 567 -9633us[-7826us] +/- 115ms</span></span>
<span class="line"><span>^- ns2.pulsation.fr 2 10 377 311 -75ms[ -73ms] +/- 250ms</span></span></code></pre></div><p><code>chronyc</code> 工具可以對每個源進行統計，比如使用 <code>sourcestats</code> 命令獲得漂移速率和進行偏移估計。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc sourcestats</span></span>
<span class="line"><span>210 Number of sources = 8</span></span>
<span class="line"><span>Name/IP Address NP NR Span Frequency Freq Skew Offset Std Dev</span></span>
<span class="line"><span>==============================================================================</span></span>
<span class="line"><span>chilipepper.canonical.com 32 16 89m +6.293 14.345 +30ms 24ms</span></span>
<span class="line"><span>golem.canonical.com 32 17 89m +0.312 18.887 +20ms 33ms</span></span>
<span class="line"><span>pugot.canonical.com 32 18 89m +0.281 11.237 +3307us 23ms</span></span>
<span class="line"><span>alphyn.canonical.com 31 20 88m -4.087 8.910 -58ms 17ms</span></span>
<span class="line"><span>dadns.cdnetworks.co.kr 29 16 76m -1.094 9.895 -83ms 14ms</span></span>
<span class="line"><span>t1.time.sg3.yahoo.com 32 16 91m +0.153 1.952 +2835us 4044us</span></span>
<span class="line"><span>sin1.m-d.net 29 13 83m +0.049 6.060 -8466us 9940us</span></span>
<span class="line"><span>ns2.pulsation.fr 32 17 88m +0.784 9.834 -62ms 22ms</span></span></code></pre></div><p>如果你的系統沒有連接到互聯網，你需要告知 Chrony 系統沒有連接到 互聯網。為了這樣做，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chronyc offline</span></span>
<span class="line"><span>[sudo] password for sk:</span></span>
<span class="line"><span>200 OK</span></span></code></pre></div><p>為了確認你的 NTP 源的狀態，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc activity</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>0 sources online</span></span>
<span class="line"><span>8 sources offline</span></span>
<span class="line"><span>0 sources doing burst (return to online)</span></span>
<span class="line"><span>0 sources doing burst (return to offline)</span></span>
<span class="line"><span>0 sources with unknown address</span></span></code></pre></div><p>可以看到，我的所有源此時都是離線狀態。</p><p>一旦你連接到互聯網，只需要使用命令告知 Chrony 你的系統已經回到在線狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chronyc online</span></span>
<span class="line"><span>200 OK</span></span></code></pre></div><p>為了查看 NTP 源的狀態，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc activity</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>8 sources online</span></span>
<span class="line"><span>0 sources offline</span></span>
<span class="line"><span>0 sources doing burst (return to online)</span></span>
<span class="line"><span>0 sources doing burst (return to offline)</span></span>
<span class="line"><span>0 sources with unknown address</span></span></code></pre></div><p>所有選項和參數的詳細解釋，請參考其幫助手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man chronyc</span></span>
<span class="line"><span>$ man chronyd</span></span></code></pre></div><p>這就是文章的所有內容。希望對你有所幫助。在隨後的教程中，我們會看到如何使用 Chrony 啓動一個本地的 NTP 服務器並且配置客户端來使用這個服務器同步時間。</p><p>保持關注！</p><hr>`,25)),p("p",null,[s[4]||(s[4]=n("via: ",-1)),e(a,{href:"https://www.ostechnix.com/chrony-an-alternative-ntp-client-and-server-for-unix-like-systems/"},{default:i(()=>[...s[3]||(s[3]=[n("https://www.ostechnix.com/chrony-an-alternative-ntp-client-and-server-for-unix-like-systems/",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=n("作者：",-1)),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[5]||(s[5]=[n("SK",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),e(a,{href:"https://github.com/zianglei"},{default:i(()=>[...s[7]||(s[7]=[n("zianglei",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const v=t(d,[["render",h]]);export{C as __pageData,v as default};
